 @Autowired protected IncomingQualityService service;@Autowired protected IncomingQualityQueryService queries;@Autowired protected QcSpecificationService qc;@Autowired protected WmsService wms;@Autowired protected UnitService units;@Autowired protected MaterialService materials;@Autowired protected SupplierService suppliers;@Autowired protected MaterialSupplierService links;@Autowired protected ObjectMapper json;@Autowired protected JdbcTemplate jdbc;@Autowired protected SignatureTransactionService verifier;@Autowired protected PlatformTransactionManager transactions;
